-- ============================================================ -- ICT702 Supplementary Assignment - DDL Script -- Database: ICT702_Nusrat_Supplementary_Assignment -- ============================================================  start transaction;  -- ------------------------------------------------------------ -- Table: QUALIFICATION -- (Created first - referenced by CANDIDATE_QUALIFICATION, --  COURSE, COURSE_PREREQUISITE, and OPENING) -- ------------------------------------------------------------ create table QUALIFICATION (     Qual_ID          int             not null auto_increment,     Qual_Name        varchar(100)    not null,     Qual_Description varchar(500)    null,     constraint PK_QUALIFICATION primary key (Qual_ID) );  -- ------------------------------------------------------------ -- Table: CANDIDATE -- ------------------------------------------------------------ create table CANDIDATE (     Candidate_No int             not null auto_increment,     First_Name   varchar(50)     not null,     Last_Name    varchar(50)     not null,     Address      varchar(200)    null,     Phone        varchar(20)     null,     Email        varchar(100)    null,     constraint PK_CANDIDATE primary key (Candidate_No) );  -- ------------------------------------------------------------ -- Table: CANDIDATE_QUALIFICATION -- ------------------------------------------------------------ create table CANDIDATE_QUALIFICATION (     Candidate_No int     not null,     Qual_ID      int     not null,     Date_Earned  date    null,     constraint PK_CANDIDATE_QUALIFICATION         primary key (Candidate_No, Qual_ID),     constraint FK_CANDQUAL_CANDIDATE         foreign key (Candidate_No)         references CANDIDATE (Candidate_No),     constraint FK_CANDQUAL_QUALIFICATION         foreign key (Qual_ID)         references QUALIFICATION (Qual_ID) );  -- ------------------------------------------------------------ -- Table: COURSE -- ------------------------------------------------------------ create table COURSE (     Course_ID          int             not null auto_increment,     Qual_ID            int             not null,     Course_Name        varchar(100)    not null,     Course_Description varchar(500)    null,     Duration_Hours     decimal(5,2)    null,     constraint PK_COURSE primary key (Course_ID),     constraint FK_COURSE_QUALIFICATION         foreign key (Qual_ID)         references QUALIFICATION (Qual_ID) );  -- ------------------------------------------------------------ -- Table: COURSE_PREREQUISITE -- ------------------------------------------------------------ create table COURSE_PREREQUISITE (     Course_ID      int not null,     Prereq_Qual_ID int not null,     constraint PK_COURSE_PREREQUISITE         primary key (Course_ID, Prereq_Qual_ID),     constraint FK_COURSEPREREQ_COURSE         foreign key (Course_ID)         references COURSE (Course_ID),     constraint FK_COURSEPREREQ_QUALIFICATION         foreign key (Prereq_Qual_ID)         references QUALIFICATION (Qual_ID) );  -- ------------------------------------------------------------ -- Table: TRAINING_SESSION -- ------------------------------------------------------------ create table TRAINING_SESSION (     Session_ID     int             not null auto_increment,     Course_ID      int             not null,     Session_Date   date            not null,     Location       varchar(200)    null,     Fee            decimal(10,2)   not null,     Max_Candidates int             null,     constraint PK_TRAINING_SESSION primary key (Session_ID),     constraint FK_TRAININGSESSION_COURSE         foreign key (Course_ID)         references COURSE (Course_ID) );  -- ------------------------------------------------------------ -- Table: SESSION_REGISTRATION -- ------------------------------------------------------------ create table SESSION_REGISTRATION (     Candidate_No      int             not null,     Session_ID        int             not null,     Registration_Date date            null,     Fee_Paid          decimal(10,2)   null,     constraint PK_SESSION_REGISTRATION         primary key (Candidate_No, Session_ID),     constraint FK_SESSIONREG_CANDIDATE         foreign key (Candidate_No)         references CANDIDATE (Candidate_No),     constraint FK_SESSIONREG_TRAININGSESSION         foreign key (Session_ID)         references TRAINING_SESSION (Session_ID) );  -- ------------------------------------------------------------ -- Table: COMPANY -- ------------------------------------------------------------ create table COMPANY (     Company_ID   int             not null auto_increment,     Company_Name varchar(100)    not null,     Address      varchar(200)    null,     Phone        varchar(20)     null,     constraint PK_COMPANY primary key (Company_ID) );  -- ------------------------------------------------------------ -- Table: OPENING -- ------------------------------------------------------------ create table OPENING (     Opening_No int             not null auto_increment,     Company_ID int             not null,     Qual_ID    int             not null,     Start_Date date            not null,     End_Date   date            null,     Hourly_Pay decimal(10,2)   not null,     constraint PK_OPENING primary key (Opening_No),     constraint FK_OPENING_COMPANY         foreign key (Company_ID)         references COMPANY (Company_ID),     constraint FK_OPENING_QUALIFICATION         foreign key (Qual_ID)         references QUALIFICATION (Qual_ID) );  -- ------------------------------------------------------------ -- Table: PLACEMENT_RECORD -- ------------------------------------------------------------ create table PLACEMENT_RECORD (     Opening_No         int             not null,     Candidate_No       int             not null,     Total_Hours_Worked decimal(8,2)    null,     Placement_Date     date            not null,     constraint PK_PLACEMENT_RECORD         primary key (Opening_No, Candidate_No),     constraint FK_PLACEMENT_OPENING         foreign key (Opening_No)         references OPENING (Opening_No),     constraint FK_PLACEMENT_CANDIDATE         foreign key (Candidate_No)         references CANDIDATE (Candidate_No) );  -- ------------------------------------------------------------ -- Table: JOB_HISTORY -- ------------------------------------------------------------ create table JOB_HISTORY (     History_ID   int             not null auto_increment,     Candidate_No int             not null,     Opening_No   int             not null,     Start_Date   date            not null,     End_Date     date            null,     Hours_Worked decimal(8,2)    null,     constraint PK_JOB_HISTORY primary key (History_ID),     constraint FK_JOBHISTORY_CANDIDATE         foreign key (Candidate_No)         references CANDIDATE (Candidate_No),     constraint FK_JOBHISTORY_OPENING         foreign key (Opening_No)         references OPENING (Opening_No) );  commit;